    agregar("G-10-55-30", CLASE_55, "L3", "Prueba de aislamiento en arnes pasacables de puerta del conductor: ensayo con megohmetro a 250V arroja resistencia de aislamiento de solo 150 kiloohmios entre cable de senal LOCK y cable de masa por aislamiento cuarteado y humedad marina acumulada en el pasamuros.", "TECNICO", "MEGOHMETRO_ARNES", "aislamiento_150kohm_fuelle, cables_cuarteados_humedad", "falla_mecanismo_llave", "", "NO", "NO", "", "L3 aislamiento degradado 150k en pasacables")
