    agregar("G-10-56-08", CLASE_56, "L1", "La puerta trasera quedo entreabierta y no termina de trabar en el segundo clic.", "COLOQUIAL", "ENGANCHE_PUERTA", "sin_segundo_clic_enganche", "NO_REPORTA", "", "SI", "NO", "", "L1 no entra segundo clic de enganche")
    agregar("G-10-56-09", CLASE_56, "L1", "Jalo la palanquita interior para salir y no destraba la puerta.", "COLOQUIAL", "APERTURA_INTERIOR", "manija_interior_sin_destrabe", "NO_REPORTA", "", "SI", "NO", "", "L1 manija interior no destraba")
    agregar("G-10-56-10", CLASE_56, "L1", "Siento un ruido a lata suelta adentro de la puerta cuando intento abrirla.", "COLOQUIAL", "ACCIONAMIENTO", "ruido_varilla_suelta", "NO_REPORTA", "", "SI", "NO", "", "L1 varilla suelta en puerta")

    # L2 (15 casos)
    agregar("G-10-56-11", CLASE_56, "L2", "El pestillo electrico acciona y suena con fuerza al presionar el mando, pero la puerta rebota contra el parante porque la boca de la chapa golpea desfasada 5 mm abajo del perno cerradero.", "TECNICO", "INTENTO_CIERRE", "actuador_electrico_fuerte_ok, puerta_rebota_desalineada_5mm", "falla_electrica_cierre", "", "NO", "SI", CLASE_55, "L2 actuador ok pero desalineacion mecanica 5mm")
    agregar("G-10-56-12", CLASE_56, "L2", "La cerradura quedo totalmente bloqueada mecanicamente por grasa solidificada y polvo acumulado; la llave gira solo 10 grados y se traba en seco sin mover el pestillo.", "COLOQUIAL", "USO_LLAVE", "grasa_solidificada_polvo, llave_traba_10_grados", "fallo_actuador_electrico", "", "NO", "SI", CLASE_55, "L2 bloqueo por grasa y suciedad en mecanismo")
    agregar("G-10-56-13", CLASE_56, "L2", "Al tirar de la manija exterior de la puerta se siente que no ofrece resistencia; tras retirar el tapiz se observa que la varilla metalica se solto del retenedor de plastico de la cerradura.", "TECNICO", "DESARME_TAPIZ", "varilla_suelta_de_grapa_plastica, manija_sin_resistencia", "falla_solenoide", "", "NO", "SI", CLASE_55, "L2 varilla mecanica desenganchada de grapa")
    agregar("G-10-56-14", CLASE_56, "L2", "Las bisagras de la puerta del conductor presentan holgura severa; al cerrar hay que levantar la puerta desde la manilla hacia arriba para que el pestillo calce en el cerradero.", "COLOQUIAL", "CIERRE_PUERTA", "holgura_bisagras_puerta_caida, levantar_para_cerrar", "falla_electrica", "", "NO", "NO", "", "L2 bisagras vencidas desalinean pestillo")
    agregar("G-10-56-15", CLASE_56, "L2", "El perno cerradero (striker) del pilar B se aflojo y se desplazo hacia adentro; la puerta queda suelta vibrando en marcha y requiere portazo violento para trabar en el primer seguro.", "TECNICO", "INSPECCION_STRIKER", "perno_striker_suelto_desplazado, vibracion_puerta_marcha", "actuador_quemado", "", "NO", "SI", CLASE_55, "L2 perno cerradero striker aflojado")
    agregar("G-10-56-16", CLASE_56, "L2", "El seguro para ninos (child lock) quedo atascado mecanicamente a mitad de carrera; la puerta no se puede abrir desde adentro pero desde afuera abre con normalidad.", "TECNICO", "PRUEBA_MECANICA", "child_lock_trabado_mitad, sin_apertura_interior", "falla_cierre_centralizado", "", "NO", "SI", CLASE_55, "L2 traba mecanica seguro ninos")
    agregar("G-10-56-17", CLASE_56, "L2", "El pestillo de la chapa tiene el muelle espiral interno de retorno roto; la unas de traba no regresan a su posicion de reposo y la puerta no retiene al empujarla contra el marco.", "TECNICO", "INSPECCION_CHAPA", "resorte_retorno_roto, unas_no_retienen", "falla_solenoide", "", "NO", "NO", "", "L2 resorte de retorno de unas roto")
    agregar("G-10-56-18", CLASE_56, "L2", "El bombin de la cerradura mecanica fue forzado con destornillador; las laminillas internas de combinacion estan dobladas y bloquean el giro de la llave original.", "COLOQUIAL", "REVISION_BOMBIN", "bombin_forzado_laminillas_dobladas, llave_no_entra", "falla_alarma", "", "NO", "NO", "", "L2 bombin forzado con laminillas dobladas")
    agregar("G-10-56-19", CLASE_56, "L2", "La compuerta trasera de carga presenta descuadre tras un golpe leve en el parachoques; el pestillo mecanico hace tope de metal contra metal sin permitir que el gancho cierre.", "TECNICO", "INSPECCION_CARROCERIA", "descuadre_porton_trasero_choque, gancho_hace_tope_metal", "falla_cierre_electrico", "", "NO", "SI", CLASE_55, "L2 descuadre estructural de porton tras colision")
    agregar("G-10-56-20", CLASE_56, "L2", "La cerradura de la puerta del copiloto abre y cierra electricamente con el boton, pero la chapa mecanica tiene juego excesivo y la puerta hace ruido de sonajero en caminos de tierra.", "COLOQUIAL", "MARCHA_CAMINO_TIERRA", "chapa_juego_excesivo_sonajero, cierre_electrico_ok", "falla_amortiguador", "", "NO", "NO", "", "L2 holgura en pestillo produce ruido en baches")
    agregar("G-10-56-21", CLASE_56, "L2", "Al accionar el mando central se escucha el motor trabajar con vigor, pero el cerrojo mecanico no traba porque el brazo de plastico que conecta con la cerradura esta partido en dos.", "TECNICO", "DESARME_INTERIOR", "brazo_plastico_partido, motor_trabaja_con_fuerza", "falla_motor_cierre", "", "NO", "SI", CLASE_55, "L2 brazo plastico de enlace quebrado")
    agregar("G-10-56-22", CLASE_56, "L2", "El pestillo de la puerta del conductor se traba al intentar destrabar manualmente con la varilla interior; se aprecia oxido denso en los ejes de articulacion de la cerradura.", "TECNICO", "INSPECCION_VISUAL", "oxido_denso_articulacion, varilla_interior_durisima", "falla_electrica_bcm", "", "NO", "SI", CLASE_55, "L2 oxidacion severa en mecanismos de chapa")
    agregar("G-10-56-23", CLASE_56, "L2", "El cerrojo de seguridad de la guantera se quedo trabado en posicion cerrada; la manija de plastico gira libre sin retraer los pestillos laterales de enganche.", "COLOQUIAL", "CABINA", "cerrojo_guantera_trabado, manija_gira_en_falso", "falla_electrica", "", "NO", "NO", "", "L2 traba mecanica cerrojo guantera")
    agregar("G-10-56-24", CLASE_56, "L2", "La puerta trasera no abre desde el exterior porque el cable Bowden de traccion tiene el tope de plomo zafado en la corredera de la manilla.", "TECNICO", "INSPECCION_MANILLA", "cable_bowden_tope_plomo_zafado, manilla_exterior_inutil", "falla_actuador", "", "NO", "SI", CLASE_55, "L2 cable Bowden desenganchado de manija")
    agregar("G-10-56-25", CLASE_56, "L2", "Tras pintar la puerta se montaron las cerraduras sin calibrar el centrado del cerradero; la puerta queda salida 4 mm respecto a la aleta trasera y filtra aire a alta velocidad.", "TECNICO", "CARRETERA_VIENTO", "puerta_salida_4mm_filtra_aire, cerradero_mal_calibrado", "falla_burlete_goma", "", "NO", "NO", "", "L2 mala calibracion de cerradero post pintura")

    # L3 (15 casos)
    agregar("G-10-56-26", CLASE_56, "L3", "Evaluacion metrologica de alineacion de carroceria y cerradura: el perno cerradero (striker) del pilar B presenta un descentramiento vertical de 6.2 mm respecto al eje central de la traba de la chapa, provocando que la uña de doble enganche golpee la cabeza del perno y rebote sin cerrar; holgura en perno de bisagra superior medida en 1.8 mm.", "TECNICO", "METROLOGIA_ALINEACION", "descentramiento_striker_6_2mm, holgura_bisagra_1_8mm, puerta_rebota", "falla_actuador_electrico", "", "NO", "SI", CLASE_55, "L3 descentramiento vertical striker 6.2mm")
    agregar("G-10-56-27", CLASE_56, "L3", "Diagnostico mecanico de cerradura de puerta: desmontaje de conjunto de chapa revela resorte espiral de torsion fracturado en dos secciones (resorte de retorno del trinquete de retencion). Al accionar manualmente la leva, el trinquete no vuelve por gravedad ni muelle, quedando en posicion abierta y requiriendo reemplazo mecanico del cerrojo.", "TECNICO", "DESARME_BANCO_CHAPA", "resorte_torsion_fracturado, trinquete_no_retorna, chapa_abierta", "falla_solenoide_electrico", "", "NO", "SI", CLASE_55, "L3 resorte espiral de torsion partido en dos")
    agregar("G-10-56-28", CLASE_56, "L3", "Metrologia de esfuerzo de cierre de puerta con dinamometro push-pull: la fuerza de impacto requerida para alcanzar el enganche secundario es de 145 Newtons (especificacion OEM normal: 35 a 45 N). Ajuste de posicion del cerradero en ranuras colisas de pilar reduce la fuerza requerida a 40 N con alineacion perfecta de linea de moldura.", "TECNICO", "DINAMOMETRO_PUSH_PULL", "fuerza_cierre_145n_vs_45n_oem, ajuste_colisas_cerradero_40n", "falla_cierre_centralizado", "", "NO", "SI", CLASE_55, "L3 dinamometro 145N de fuerza de cierre")
    agregar("G-10-56-29", CLASE_56, "L3", "Inspeccion de cerradura mecanica con microscopio de taller: el bombin de tambor de llave de encendido/puerta presenta cinco wafers (laminas de combinacion de laton) atascados con rebaba metalica de 0.3 mm por uso de llave clonada de perfil incorrecto, impidiendo el giro de 90 grados hacia posicion de desbloqueo.", "TECNICO", "MICROSCOPIO_LAMINILLAS", "wafers_atascados_rebaba_0_3mm, bombin_trabado, llave_perfil_falso", "falla_alarma_inmovilizador", "", "NO", "NO", "", "L3 cinco wafers de bombin con rebaba 0.3mm")
    agregar("G-10-56-30", CLASE_56, "L3", "Comprobacion de varillaje mecanico de puerta: la varilla de traccion entre manija exterior y chapa tiene una deformacion angular por flexion de 28 grados tras forzamiento de puerta; la carrera util de tiro se redujo de 14 mm a solo 6 mm, siendo insuficiente para liberar la leva de desenganche del pestillo.", "TECNICO", "BANCO_VARILLAJE", "varilla_doblada_28_grados, carrera_util_6mm_vs_14mm", "actuador_danado", "", "NO", "SI", CLASE_55, "L3 varilla doblada carrera reducida a 6mm")
    agregar("G-10-56-31", CLASE_56, "L3", "Desarme de cerradura de porton trasero: leva de accionamiento de zamak presenta fractura limpia por fatiga en la espiga de articulacion con el tirador manual; el micromotor electrico actua a la perfeccion enviando su recorrido pero la conexion fisica hacia el gancho se encuentra totalmente desvinculada.", "TECNICO", "INSPECCION_FRACTURA_ZAMAK", "espiga_zamak_fracturada_fatiga, motor_electrico_ok, gancho_desvinculado", "falla_motor_cierre", "", "NO", "SI", CLASE_55, "L3 espiga de zamak quebrada con motor ok")
    agregar("G-10-56-32", CLASE_56, "L3", "Prueba de ajuste de luz de puerta y enrase de carroceria: medicion con galga de espesores cónica revela holgura de holgura superior de 8.5 mm e inferior de 2.0 mm (descuadre trapezoidal de 6.5 mm); pasador de bisagra inferior de acero cementado presenta desgaste de 1.4 mm con juego axial pronunciado.", "TECNICO", "GALGA_CONICA_CARROCERIA", "descuadre_luz_6_5mm, desgaste_pasador_bisagra_1_4mm", "falla_cerradura_electrica", "", "NO", "NO", "", "L3 galga conica holgura trapezoidal 6.5mm")
    agregar("G-10-56-33", CLASE_56, "L3", "Analisis de falla en cerrojo de puerta corrediza: el tope de bloqueo inferior de nylon se encuentra desgastado en 4 mm y lleno de tierra; al cerrar la corredera la guia metalica hace tope seco sin permitir que el pestillo gire los 45 grados necesarios para el enganche de seguridad.", "TECNICO", "TALLER_CARROCERIA", "tope_nylon_desgastado_4mm, pestillo_no_gira_45_grados", "falla_sensor_puerta", "", "NO", "NO", "", "L3 tope nylon gastado impide giro 45 grados")
    agregar("G-10-56-34", CLASE_56, "L3", "Inspeccion de cable Bowden de manija interior: funda exterior de acero enrollado presenta aplastamiento por tornillo autorroscante de parlante aftermarket colocado incorrectamente; cable interior acerado de 1.5 mm aprisionado sin desplazamiento axial bajo traccion manual de 80 N.", "TECNICO", "INSPECCION_CABLE_BOWDEN", "funda_cable_aplastada_tornillo, cable_1_5mm_aprisionado", "falla_botonera_electrica", "", "NO", "NO", "", "L3 cable Bowden aplastado por tornillo")
    agregar("G-10-56-35", CLASE_56, "L3", "Verificacion de geometria de cerradura: el striker presenta surco de desgaste mecanico de 2.2 mm de profundidad producido por roce continuo durante 80,000 km; el trinquete de retencion se desliza fuera del surco en curvas fuertes a la izquierda, abriendose la puerta en primer seguro.", "TECNICO", "METROLOGIA_STRIKER", "surco_desgaste_striker_2_2mm, puerta_abre_en_curva", "falla_actuador_electrico", "", "NO", "SI", CLASE_55, "L3 surco de desgaste 2.2mm en perno cerradero")
    agregar("G-10-56-36", CLASE_56, "L3", "Evaluacion de sistema de traba de capot: el pestillo de seguridad secundario tiene el eje de articulacion oxidado y pegado en posicion abierta por sulfatacion salina; al soltar la palanca de cabina el gancho principal libera pero el segundo gancho no traba de forma segura ante viento frontal.", "TECNICO", "INSPECCION_CAPOT", "pestillo_secundario_capot_oxidado_pegado, riesgo_apertura", "falla_cable_traccion", "", "NO", "NO", "", "L3 pestillo secundario capot oxidado pegado")
    agregar("G-10-56-37", CLASE_56, "L3", "Desarme de conjunto cerradura en camioneta: uña de retencion principal recubierta de goma plastisol presenta desprendimiento del elastomero; el juego radial metal con metal de 3.5 mm provoca cascabeleo sordo en el pilar B a 60 km/h sobre asfalto rugoso con puerta firmemente asegurada.", "TECNICO", "TALLER_CHAPA", "desprendimiento_plastisol_una, juego_3_5mm_cascabeleo", "ruido_suspension", "", "NO", "NO", "", "L3 desprendimiento plastisol cascabeleo 3.5mm")
    agregar("G-10-56-38", CLASE_56, "L3", "Medicion de par de giro en bombin de cerradura con torquimetro de precision: torque para girar llave en sentido horario supera los 4.8 Nm (especificacion de esfuerzo suave menor a 0.6 Nm) debido a contaminacion por grafito en polvo humedecido con aceite vegetal que formo pasta abrasiva.", "TECNICO", "TORQUIMETRO_BOMBIN", "par_giro_4_8nm_vs_0_6nm, pasta_grafito_aceite_obstruccion", "falla_electrica_llave", "", "NO", "NO", "", "L3 torquimetro en bombin 4.8 Nm por pasta")
    agregar("G-10-56-39", CLASE_56, "L3", "Comprobacion de chapa de maletero en vehiculo sedan: cerradero montado sobre travesano trasero deformado hacia adelante 8 mm tras impacto de estacionamiento; al accionar apertura remota el solenoide dispara pero la presion de precarga de los burletes impide liberar el diente mecanico.", "TECNICO", "REVISION_TRAVESANO", "travesano_deformado_8mm_choque, precarga_excesiva_burletes", "falla_solenoide_maletero", "", "NO", "SI", CLASE_55, "L3 travesano deformado 8mm precarga burletes")
    agregar("G-10-56-40", CLASE_56, "L3", "Inspeccion tecnica de mecanismo de seguro infantil: selector rotativo de cerradura presenta la lengueta plastica selectora quebrada internamente a 90 grados; el trinquete de desbloqueo interior permanece desconectado de forma permanente sin posibilidad de abrir desde cabina.", "TECNICO", "DESARME_MECANISMO_CHILD", "lengueta_selectora_quebrada, trinquete_interior_desconectado", "falla_cierre_electrico", "", "NO", "SI", CLASE_55, "L3 lengueta de seguro infantil quebrada a 90 grados")

    # =========================================================================
    # CLASE 57: Elevalunas electrico o guaya de alzacristales rota o trabada
    # =========================================================================
    # L1 (10 casos)
    agregar("G-10-57-01", CLASE_57, "L1", "El vidrio de la ventana del conductor no quiere subir.", "COLOQUIAL", "INTENTO_SUBIDA", "vidrio_no_sube", "NO_REPORTA", "", "SI", "NO", "", "L1 ventana no sube")
    agregar("G-10-57-02", CLASE_57, "L1", "Se escucho un golpe seco dentro de la puerta y la luna se cayo sola.", "COLOQUIAL", "CAIDA_VIDRIO", "golpe_puerta, luna_caida", "NO_REPORTA", "", "SI", "NO", "", "L1 vidrio se cayo solo")
    agregar("G-10-57-03", CLASE_57, "L1", "Presiono el boton de la ventana y solo suena un crujido de cables adentro.", "COLOQUIAL", "ACCIONAMIENTO", "crujido_cables_puerta", "NO_REPORTA", "", "SI", "NO", "", "L1 crujido de cables en puerta")
    agregar("G-10-57-04", CLASE_57, "L1", "La ventana del copiloto sube muy chueca y se frena a mitad de camino.", "COLOQUIAL", "SUBIDA_VIDRIO", "ventana_chueca_frenada", "NO_REPORTA", "", "SI", "NO", "", "L1 ventana sube chueca y frena")
    agregar("G-10-57-05", CLASE_57, "L1", "El motor del alzacristales suena pero el vidrio no se mueve ni un centimetro.", "COLOQUIAL", "ACCIONAMIENTO", "motor_suena_sin_movimiento", "NO_REPORTA", "", "SI", "NO", "", "L1 motor suena vidrio quieto")
    agregar("G-10-57-06", CLASE_57, "L1", "No funciona la ventana trasera derecha con ningun interruptor.", "COLOQUIAL", "COMANDO_BOTON", "ventana_trasera_inoperante", "NO_REPORTA", "", "SI", "NO", "", "L1 ventana trasera inoperante")
    agregar("G-10-57-07", CLASE_57, "L1", "Tengo que agarrar el vidrio con las dos manos y jalarlo hacia arriba para cerrarlo.", "COLOQUIAL", "CIERRE_FORZADO", "jalar_vidrio_manos", "NO_REPORTA", "", "SI", "NO", "", "L1 ayuda manual obligada")
    agregar("G-10-57-08", CLASE_57, "L1", "La ventana baja rapido pero para subir le cuesta una eternidad.", "COLOQUIAL", "VELOCIDAD_VENTANA", "subida_lenta_pesada", "NO_REPORTA", "", "SI", "NO", "", "L1 subida extremadamente lenta")
    agregar("G-10-57-09", CLASE_57, "L1", "El boton del elevalunas en la consola se siente suelto y no hace contacto.", "COLOQUIAL", "BOTONERA", "boton_suelto_sin_contacto", "NO_REPORTA", "", "SI", "NO", "", "L1 interruptor de vidrio suelto")
    agregar("G-10-57-10", CLASE_57, "L1", "Se cayo el vidrio dentro de la puerta y suena que raspa todo al andar.", "COLOQUIAL", "EN_MARCHA", "vidrio_caido_raspa_puerta", "NO_REPORTA", "", "SI", "NO", "", "L1 vidrio dentro de puerta raspa")

    # L2 (15 casos)
    agregar("G-10-57-11", CLASE_57, "L2", "Al presionar el boton del alzacristales se escucha claramente el giro del motor electrico dentro de la puerta, pero el cristal se fue al fondo de la cavidad debido a rotura de la guaya de acero.", "TECNICO", "ACCIONAMIENTO_BOTON", "motor_gira_ok, guaya_rota, cristal_caido", "falla_motor_electrico", "", "NO", "NO", "", "L2 motor gira pero guaya rota cristal al fondo")
    agregar("G-10-57-12", CLASE_57, "L2", "La ventana del conductor sube torcida hacia adelante y se atasca a 10 cm del marco superior; la grapa plastica deslizadera del riel vertical se quebro por resecamiento.", "TECNICO", "SUBIDA_CRISTAL", "ventana_torcida_atasco, grapa_plastica_riel_quebrada", "falla_bateria", "", "NO", "SI", CLASE_48, "L2 grapa plastica de riel rota cristal torcido")
    agregar("G-10-57-13", CLASE_57, "L2", "Al operar el comando del alzacristales se produce un sonido de triturado metalico dentro de la puerta; el cable acerado se salio de la polea y se enredo en el tambor de bobinado.", "TECNICO", "PRUEBA_OPERATIVA", "sonido_triturado_cable, cable_enredado_tambor", "falla_cerradura_puerta", "", "NO", "SI", CLASE_55, "L2 cable acerado enredado en carril tambor")
    agregar("G-10-57-14", CLASE_57, "L2", "Con el vehiculo en marcha a 14V la ventana sube a velocidad normal, pero con motor apagado a 12.5V el cristal sube extremadamente lento por suciedad en colisas y carbones de motor desgastados.", "TECNICO", "COMPARACION_TENSION", "subida_lenta_motor_apagado, colisas_sucias_carbones", "bateria_defectuosa", "", "NO", "SI", CLASE_48, "L2 consumo elevado por roce de guias vs bateria")
    agregar("G-10-57-15", CLASE_57, "L2", "La ventana del pasajero baja sin problemas pero al darle a subir no hay reaccion; el interruptor individual del copiloto tiene los platinos internos carbonizados sin paso de 12V.", "TECNICO", "PRUEBA_INTERRUPTOR", "baja_ok_no_sube, platinos_carbonizados_interruptor", "falla_motor_alzacristal", "", "NO", "NO", "", "L2 platinos de contacto carbonizados en switch")
    agregar("G-10-57-16", CLASE_57, "L2", "El sistema antipinzamiento (anti-pinch) se activa automaticamente cuando el cristal llega al 70% de su recorrido invirtiendo la marcha, debido a resistencia por colisa de goma hinchada.", "TECNICO", "SUBIDA_AUTOMATICA", "antipinch_activa_rebota, resistencia_colisa_goma", "falla_motor_quemado", "", "NO", "NO", "", "L2 activacion erronea de antipinch por roce")
    agregar("G-10-57-17", CLASE_57, "L2", "Al desmontar el panel de la puerta se constata que el cable flexible de acero de 1.5 mm se deshilacho, trabando la corredera en el riel de aluminio e impidiendo el movimiento manual.", "TECNICO", "DESARME_TAPIZ", "cable_deshilachado_trabado, corredera_inmovil", "falla_electrica_cableado", "", "NO", "NO", "", "L2 cable deshilachado traba corredera")
    agregar("G-10-57-18", CLASE_57, "L2", "El cristal delantero derecho quedo suelto: se puede empujar hacia abajo con la palma de la mano con facilidad porque los pernos de fijacion de la mordaza inferior del vidrio se aflojaron.", "COLOQUIAL", "EMPUJE_MANUAL", "vidrio_baja_con_palma_mano, mordaza_aflojada", "motor_quemado", "", "NO", "NO", "", "L2 mordaza inferior de vidrio aflojada")
    agregar("G-10-57-19", CLASE_57, "L2", "La botonera principal del conductor no opera ningun cristal pero las botoneras individuales de cada puerta si funcionan; fusible termico o pista de alimentacion de la botonera maestra danada.", "TECNICO", "REVISION_BOTONERA_MASTER", "botonera_maestra_inoperante, botoneras_individuales_ok", "falla_fusible_general", "", "NO", "NO", "", "L2 botonera maestra del piloto inoperante")
    agregar("G-10-57-20", CLASE_57, "L2", "El motor del alzacristales calienta excesivamente tras tres intentos de subida y se apaga por proteccion bimetalica interna; el riel central carece totalmente de lubricacion y tiene oxido.", "TECNICO", "TALLER_REVISION", "motor_calienta_corte_termico, riel_sin_lubricacion_oxido", "falla_alternador", "", "NO", "SI", CLASE_47, "L2 corte termico de motor por falta lubricacion")
    agregar("G-10-57-21", CLASE_57, "L2", "Al activar la funcion de confort para subir lunas desde la llave el cristal trasero izquierdo no se mueve; en la puerta delantera el cierre centralizado opera con normalidad.", "TECNICO", "MODO_CONFORT_LLAVE", "confort_lunas_trasera_falla, cierre_centralizado_ok", "falla_cierre_centralizado", "", "NO", "SI", CLASE_55, "L2 falla elevalunas confort vs cierre centralizado")
    agregar("G-10-57-22", CLASE_57, "L2", "El vidrio llega arriba del todo pero emite un traqueteo tipo ametralladora continua sin detener el motor; el engranaje reductor de nylon tiene la corona dentada comida.", "COLOQUIAL", "TOPE_SUPERIOR", "traqueteo_corona_reductora_barrida, no_detiene_motor", "falla_motor_quemado", "", "NO", "NO", "", "L2 corona reductora de nylon barrida en tope")
    agregar("G-10-57-23", CLASE_57, "L2", "DTC B1402 registrado en BCM referente a circuito de motor de elevalunas delantero izquierdo; medicion confirma cable de masa quebrado en el fuelle de goma de union a la carroceria.", "TECNICO", "SCANNER_CARROCERIA", "dtc_b1402, masa_quebrada_fuelle_puerta", "falla_bateria", "B1402", "NO", "SI", CLASE_48, "L2 DTC B1402 masa quebrada en fuelle")
    agregar("G-10-57-24", CLASE_57, "L2", "La guaya metalica se salio de la polea superior de reenvio y corto la carcasa plastica del soporte; el vidrio se balancea hacia los costados dentro del marco de la puerta.", "TECNICO", "INSPECCION_POLEA", "guaya_fuera_polea_superior, vidrio_balancea_costados", "falla_chapa_puerta", "", "NO", "SI", CLASE_56, "L2 guaya salida de polea y soporte quebrado")
    agregar("G-10-57-25", CLASE_57, "L2", "El motor alzacristales trasero hace clic pero no gira; al golpear levemente el panel interior con el puno el cristal baja de golpe, senal de escobillas pegadas por polvo.", "COLOQUIAL", "GOLPE_PANEL", "clic_sin_giro, arranca_con_golpe_puno, escobillas", "falla_cierre_electrico", "", "NO", "SI", CLASE_55, "L2 escobillas de motor alzacristales pegadas")

    # L3 (15 casos)
    agregar("G-10-57-26", CLASE_57, "L3", "Diagnostico de consumo de corriente en motor alzacristales: pinza amperimetrica acopla en cable de alimentacion registra 22.5 Amperios sostenidos al pulsar comando de subida (nominal 4.5A a 7.0A en subida y 12A maximo en tope mecanico). Cristal bloqueado por guaya de acero enrollada de forma asimetrica en el tambor de traccion con tres espiras cruzadas.", "TECNICO", "PINZA_AMPERIMETRICA_CORRIENTE", "consumo_22_5a_bloqueo, guaya_enredada_tambor_espiras_cruzadas", "falla_bateria", "", "NO", "SI", CLASE_48, "L3 corriente 22.5A por guaya cruzada en tambor")
    agregar("G-10-57-27", CLASE_57, "L3", "Medicion con voltimetro automotriz en conectores de motor de elevalunas: al presionar tecla en sentido subida se registran 12.6V directos entre terminales 1 y 2, pero el rotor permanece inmovil. Medicion de resistencia ohmica de devanado de inducido marca infinito (circuito abierto por hilo fundido en conmutador de delgas).", "TECNICO", "MULTIMETRO_TENSION_RESISTENCIA", "tension_12_6v_presente, resistencia_infinita_abierta, inducido_quemado", "falla_interruptor", "", "NO", "NO", "", "L3 12.6V presentes inducido con circuito abierto")
    agregar("G-10-57-28", CLASE_57, "L3", "Inspeccion metrologica de cable de traccion de alzacristales: cable trenzado de acero galvanizado de 7x7 hilos (diametro 1.5 mm) presenta rotura por fatiga de traccion en el terminal prensado de plomo de la corredera; tension residual en resorte compensador es 0 N provocando desplome de masa de vidrio de 4.8 kg al fondo.", "TECNICO", "METROLOGIA_CABLE_ACERO", "rotura_cable_acero_1_5mm, terminal_prensado_roto, cristal_desplomado", "falla_cerradura_chapa", "", "NO", "SI", CLASE_56, "L3 cable 1.5mm roto terminal de plomo zafado")
    agregar("G-10-57-29", CLASE_57, "L3", "Evaluacion de resistencia de desplazamiento mecanico: fuerza de arrastre requerida para mover el cristal manualmente a lo largo del carril con dinamometro de traccion es de 95 N (especificacion de colisas limpias menor a 25 N); acumulacion de arena silicea y goma resecada genera sobrecarga que dispara bimetalico termico a los 4 segundos.", "TECNICO", "DINAMOMETRO_FRICCION_RIEL", "friccion_95n_vs_25n_maximo, colisas_con_arena, bimetalico_corta", "falla_motor_electrico", "", "NO", "NO", "", "L3 friccion en colisas de 95N satura motor")
    agregar("G-10-57-30", CLASE_57, "L3", "Lectura de codigos de falla en modulo de puerta delantera: DTC B1402 (Driver Power Window Circuit Failure) almacenado en historial; escaneo de parametros en vivo registra senal de pulsos Hall de conteo de posicion estancada en 0 Hz mientras la senal de comando de potencia permanece activa en ON.", "TECNICO", "SCANNER_PULSOS_HALL", "dtc_b1402, pulsos_hall_0hz, comando_potencia_on", "falla_sensor_ckp", "B1402", "NO", "NO", "", "L3 DTC B1402 sensor Hall de posicion en 0Hz")
    agregar("G-10-57-31", CLASE_57, "L3", "Prueba de caida de tension en botonera de elevalunas maestro: caida de 3.8V entre entrada de 12V de fusible y terminal de salida hacia puerta trasera derecha durante accionamiento; desmontaje de botonera confirma platinos de conmutacion con arco electrico y resistencia de contacto de 18 Ohmios.", "TECNICO", "CAIDA_TENSION_BOTONERA", "caida_3_8v_contactos, platinos_fogueados_18ohm", "falla_motor_trasero", "", "NO", "NO", "", "L3 caida 3.8V en platinos de botonera maestra")
    agregar("G-10-57-32", CLASE_57, "L3", "Analisis de reductor de alzacristales: desmontaje de carcasa de engranajes revela tornillo sinfin de acero templado integro, pero rueda dentada helicoidal de poliacetal (POM) de 54 dientes con sector central de 12 dientes totalmente barridos por sobreesfuerzo continuo de subida.", "TECNICO", "DESARME_REDUCTOR_POM", "sinfin_acero_ok, rueda_pom_12_dientes_barridos", "falla_electrica_cableado", "", "NO", "NO", "", "L3 engranaje de poliacetal con 12 dientes barridos")
    agregar("G-10-57-33", CLASE_57, "L3", "Comprobacion de sistema antipinzamiento electronico: sensor de efecto Hall integrado en placa de motor no genera senal cuadrada de 5V al girar; modulo de puerta interpreta perdida de pulsos de tacometro como deteccion de obstaculo fisico e invierte la marcha del cristal a los 2 segundos de subida.", "TECNICO", "OSCILOSCOPIO_HALL_5V", "sensor_hall_sin_cuadrada_5v, activacion_falsa_obstaculo, rebote_2s", "falla_cerradura", "", "NO", "SI", CLASE_55, "L3 falla de sensor Hall dispara antipinch falso")
    agregar("G-10-57-34", CLASE_57, "L3", "Prueba en rampa de taller: medicion con galga de espesores en corredera de alzacristales de tijera de doble brazo revela holgura radial de 2.4 mm en pivote central remachado; el paralelismo de las mordazas se desvia 12 mm provocando que el vidrio se enclave en la guia delantera de la puerta.", "TECNICO", "METROLOGIA_TIJERA_DOBLE", "holgura_pivote_2_4mm, desvio_paralelismo_12mm, vidrio_enclavado", "falla_guaya_rota", "", "NO", "NO", "", "L3 tijera con holgura 2.4mm desvia paralelismo")
    agregar("G-10-57-35", CLASE_57, "L3", "Inspeccion de aislamiento en arnes de puerta: cable de senal UP presenta aislamiento desgastado por roce con el filo de chapa del orificio de montaje; al presionar comando de subida el cable toca chapa chasis generando cortocircuito franco a masa y fundiendo fusible F22 de 30A.", "TECNICO", "TALLER_CORTOCIRCUITO", "aislamiento_rozado_chapa, corto_a_masa, fusible_30a_fundido", "falla_cierre_centralizado", "", "NO", "SI", CLASE_55, "L3 cable rozado con chapa quema fusible 30A")
    agregar("G-10-57-36", CLASE_57, "L3", "Evaluacion de motor paso a paso de elevalunas con bus LIN: modulo de puerta no reporta comunicacion en red (DTC U0201: Lost Communication with Door Control Module C); tension de alimentacion permanente en pin 4 es 12.5V pero linea LIN permanece en 0V por diodo TVS de proteccion en corto a masa.", "TECNICO", "SCANNER_RED_LIN", "dtc_u0201, linea_lin_0v_corto, alimentacion_12_5v_ok", "falla_bateria", "U0201", "NO", "SI", CLASE_48, "L3 DTC U0201 linea LIN en corto en puerta C")
    agregar("G-10-57-37", CLASE_57, "L3", "Diagnostico de mecanismo de guaya: polea de desvio inferior de poliamida presenta eje metalico desprendido de la pletina de montaje por fatiga de material; la guaya de traccion pierde tension operativa cayendo a 0 psi y el tambor mastica el cable de acero al activar el pulsador.", "TECNICO", "INSPECCION_POLEA_INFERIOR", "eje_polea_desprendido_pletina, guaya_destensada_masticada", "falla_mecanica_puerta", "", "NO", "SI", CLASE_56, "L3 eje de polea inferior desprendido de pletina")
    agregar("G-10-57-38", CLASE_57, "L3", "Comprobacion de mordazas de sujecion de cristal: tornillos torx de apriete flojos a 0.5 Nm (especificacion de fabrica 8.0 Nm); al bajar la corredera las almohadillas de caucho vulcanizado se deslizan sobre el vidrio sin arrastrarlo, dejando el cristal sostenido unicamente por friccion de marco.", "TECNICO", "TORQUIMETRO_MORDAZAS", "torque_mordazas_0_5nm_vs_8nm, almohadillas_patinan, cristal_suelto", "falla_motor_quemado", "", "NO", "NO", "", "L3 mordazas flojas a 0.5 Nm almohadillas patinan")
    agregar("G-10-57-39", CLASE_57, "L3", "Prueba de esfuerzo en banco dinamometrico: motor alzacristales entrega par maximo bloqueado de solo 1.2 Nm (nominal minimo 7.5 Nm); imanes permanentes de ferrita del estator quebrados en fragmentos internos por golpe en panel de puerta, provocando dispersion de flujo magnetico.", "TECNICO", "BANCO_PAR_BLOQUEADO", "par_bloqueado_1_2nm_vs_7_5nm, imanes_ferrita_quebrados", "falla_bateria", "", "NO", "SI", CLASE_48, "L3 par motor 1.2 Nm por imanes quebrados")
    agregar("G-10-57-40", CLASE_57, "L3", "Inspeccion de interruptor maestro de alzacristales con fuente de poder: corriente consumida por circuito electronico de control interno en reposo es de 180 mA (maximo admisible 2 mA) debido a condensador de filtrado SMD perforado, generando descarga lenta de bateria en estacionamiento nocturno.", "TECNICO", "TALLER_CORRIENTE_REPOSO", "consumo_reposo_180ma_botonera, condensador_smd_en_fuga", "fuga_bcm_general", "", "NO", "SI", CLASE_53, "L3 botonera elevalunas con fuga de 180mA en reposo")

    # =========================================================================
    # CLASE 58: Limpiaparabrisas o motor pluma quemado
    # =========================================================================
    # L1 (10 casos)
    agregar("G-10-58-01", CLASE_58, "L1", "Las plumillas del limpiaparabrisas no se mueven para nada.", "COLOQUIAL", "ACTIVACION_PLUMAS", "plumillas_inmoviles", "NO_REPORTA", "", "SI", "NO", "", "L1 limpiaparabrisas no se mueve")
    agregar("G-10-58-02", CLASE_58, "L1", "Prendi el limpiaparabrisas bajo la lluvia y se quedo congelado a la mitad.", "COLOQUIAL", "LLUVIA_MARCHA", "limpiaparabrisas_frenado_mitad", "NO_REPORTA", "", "SI", "NO", "", "L1 plumas frenadas a la mitad")
    agregar("G-10-58-03", CLASE_58, "L1", "Se escucha el motor del limpiador zumbando pero las plumas no barren.", "COLOQUIAL", "ACCIONAMIENTO", "motor_zumba_plumas_inmoviles", "NO_REPORTA", "", "SI", "NO", "", "L1 motor zumba sin barrer")
    agregar("G-10-58-04", CLASE_58, "L1", "Solo funciona la velocidad maxima del limpiaparabrisas, las demas estan muertas.", "COLOQUIAL", "VELOCIDADES", "solo_funciona_velocidad_alta", "NO_REPORTA", "", "SI", "NO", "", "L1 solo funciona velocidad maxima")
    agregar("G-10-58-05", CLASE_58, "L1", "Las plumas se mueven hiper lentas y parece que se van a quemar.", "COLOQUIAL", "VELOCIDAD_PLUMAS", "barrido_extremadamente_lento", "NO_REPORTA", "", "SI", "NO", "", "L1 barrido extremadamente lento")
    agregar("G-10-58-06", CLASE_58, "L1", "Salio olor a plastico quemado cerca del parabrisas y dejaron de funcionar los limpiavidrios.", "COLOQUIAL", "OLOR_QUEMADO", "olor_quemado_parabrisas, plumas_muertas", "NO_REPORTA", "", "SI", "NO", "", "L1 olor a quemado y plumas muertas")
    agregar("G-10-58-07", CLASE_58, "L1", "El limpiador trasero no barre el vidrio y se escucha trabado.", "COLOQUIAL", "LIMPIADOR_TRASERO", "limpiador_trasero_trabado", "NO_REPORTA", "", "SI", "NO", "", "L1 limpiador trasero trabado")
    agregar("G-10-58-08", CLASE_58, "L1", "Al apagar el limpiaparabrisas no regresa a su posicion abajo, se queda cruzado arriba.", "COLOQUIAL", "APAGADO_MANDO", "no_retorna_a_posicion_cero", "NO_REPORTA", "", "SI", "NO", "", "L1 plumas no retornan a cero")
    agregar("G-10-58-09", CLASE_58, "L1", "Le doy a la palanca del volante y no hace nada el limpia parabrisas.", "COLOQUIAL", "MANDO_VOLANTE", "palanca_sin_respuesta", "NO_REPORTA", "", "SI", "NO", "", "L1 palanca de plumillas sin reaccion")
    agregar("G-10-58-10", CLASE_58, "L1", "Las escobillas del parabrisas vibran y se traban a medio barrido.", "COLOQUIAL", "ACCIONAMIENTO", "escobillas_vibran_traban", "NO_REPORTA", "", "SI", "NO", "", "L1 escobillas vibran y traban")

    # L2 (15 casos)
    agregar("G-10-58-11", CLASE_58, "L2", "Con la palanca de mando en velocidad 1 y 2 no hay reaccion; al seleccionar velocidad 3 maxima las plumas barren con fuerza, debido a resistencia o bobinado de baja velocidad abierto.", "TECNICO", "PRUEBA_VELOCIDADES", "velocidad_1_y_2_inoperantes, velocidad_3_alta_ok", "falla_palanca_mando", "", "NO", "NO", "", "L2 bobinado de baja velocidad abierto")
    agregar("G-10-58-12", CLASE_58, "L2", "Al activar los limpiaparabrisas el motor emite un zumbido continuo pero los brazos no se mueven; el varillaje articulado se desprendio de la rotula plastica del motorreductor.", "TECNICO", "INSPECCION_VARILLAJE", "motor_zumba_ok, varillaje_desprendido_rotula", "motor_quemado", "", "NO", "NO", "", "L2 rotula plastica de varillaje zafada")
    agregar("G-10-58-13", CLASE_58, "L2", "Al apagar el interruptor de limpiaparabrisas las plumas se detienen instantaneamente en el medio del campo visual en vez de regresar a la posicion horizontal de reposo inferior.", "TECNICO", "APAGADO_LIMPIADORES", "parada_inmediata_medio_vidrio, switch_parada_cero_falla", "falla_motor_quemado", "", "NO", "NO", "", "L2 contacto de parada automatica park switch quemado")
    agregar("G-10-58-14", CLASE_58, "L2", "El motor del limpiaparabrisas huele a bobinado quemado y se siente hirviendo al tacto bajo el torpedo; el fusible de 20A de proteccion se funde a los 5 segundos de accionarlo.", "TECNICO", "TORPEDO_INSPECCION", "olor_bobinado_quemado, fusible_20a_funde_5s", "falla_alternador", "", "NO", "SI", CLASE_47, "L2 motor quemado quema fusible de 20A")
    agregar("G-10-58-15", CLASE_58, "L2", "El limpiaparabrisas trasero quedo atascado con la pluma a 90 grados; el eje pasante de metal a traves del cristal presenta oxido y corrosion que amarraron los bujes de bronce.", "TECNICO", "LIMPIADOR_TRASERO", "pluma_trasera_atascada_90_grados, eje_oxidado_amarrado", "falla_bateria", "", "NO", "SI", CLASE_48, "L2 eje de limpiador trasero amarrado por oxido")
    agregar("G-10-58-16", CLASE_58, "L2", "Al accionar el mando de barrido continuo se miden 12.4V en la ficha de conexion del motor de limpiaparabrisas pero el motor permanece inerte sin ningun zumbido ni consumo.", "TECNICO", "MEDICION_VOLTAJE", "tension_12_4v_en_ficha_ok, motor_totalmente_inerte", "falla_palanca_limpiaparabrisas", "", "NO", "NO", "", "L2 12.4V en motor pero circuito abierto en carbones")
    agregar("G-10-58-17", CLASE_58, "L2", "Bajo lluvia fuerte las plumas barren con extrema lentitud tardando 8 segundos por ciclo; con la luna mojada y lubricada el motor apenas tiene fuerza para arrastrar el varillaje.", "COLOQUIAL", "LLUVIA_FUERTE", "barrido_lento_8s_ciclo, motor_sin_torque", "bateria_descargada", "", "NO", "SI", CLASE_48, "L2 barrido lento 8 segundos por ciclo sin fuerza")
    agregar("G-10-58-18", CLASE_58, "L2", "Las plumas limpiaparabrisas barren de forma intermitente no programada: al encender la luz de giro o tocar la bocina se activan solas por derivacion a masa en la columna de direccion.", "TECNICO", "COLUMNA_DIRECCION", "activacion_espasmica_con_bocina, derivacion_masa", "falla_modulo_bcm", "", "NO", "NO", "", "L2 activacion falsa por derivacion a masa en palanca")
    agregar("G-10-58-19", CLASE_58, "L2", "El brazo del limpiaparabrisas del piloto barre hasta golpear el parante exterior izquierdo de la carroceria; la estria conica del eje estriado esta desgastada y safada.", "COLOQUIAL", "BARRIDO_DESFASADO", "pluma_golpea_parante, estria_eje_barrida", "falla_motor_quemado", "", "NO", "NO", "", "L2 estria conica de eje de brazo barrida")
    agregar("G-10-58-20", CLASE_58, "L2", "Escaneo de modulo de carroceria registra codigo B1130 por fallo en rele de limpiaparabrisas de velocidad baja; el motor opera normalmente si se aplica alimentacion directa con cable puente.", "TECNICO", "SCANNER_CARROCERIA", "dtc_b1130_rele_limpiaparabrisas, puente_directo_opera_ok", "falla_motor_pluma", "B1130", "NO", "NO", "", "L2 DTC B1130 en rele de limpiaparabrisas")
    agregar("G-10-58-21", CLASE_58, "L2", "El motor del limpiaparabrisas emite un chillido aspero como de engranaje seco; tras lubricar las articulaciones externas el ruido persiste en el interior del cuerpo reductor.", "COLOQUIAL", "RUIDO_MOTOR", "chillido_aspero_reductor_interno, varillaje_lubricado", "falla_correa_alternador", "", "NO", "SI", CLASE_47, "L2 reductor interno sin grasa vs correa")
    agregar("G-10-58-22", CLASE_58, "L2", "La velocidad intermitente del limpiaparabrisas dejo de funcionar tras lavar el motor con agua a presion; el rele temporizador integrado en el conector sufrio corrosion por humedad.", "TECNICO", "POST_LAVADO_MOTOR", "velocidad_intermitente_muerta, corrosion_rele_temporizador", "falla_motor_quemado", "", "NO", "NO", "", "L2 rele temporizador sulfatado post lavado")
    agregar("G-10-58-23", CLASE_58, "L2", "Ambas plumas quedan trabadas en el centro del parabrisas unicamente cuando el cristal esta seco; con lluvia barren forzadas calentando la carcasa metalica del motor.", "COLOQUIAL", "CRISTAL_SECO_VS_MOJADO", "traba_en_seco_calentamiento_motor, barren_forzadas", "falla_bateria", "", "NO", "SI", CLASE_48, "L2 motor pierde torque con roce en seco")
    agregar("G-10-58-24", CLASE_58, "L2", "El sensor de lluvia del parabrisas activa la peticion de barrido pero el conjunto motorreductor no responde; con la palanca manual en modo fijo continuo tampoco reacciona.", "TECNICO", "SENSOR_LLUVIA_AUTO", "sensor_lluvia_activa_sin_respuesta, modo_manual_tampoco", "falla_sensor_lluvia", "", "NO", "NO", "", "L2 falla de motor descarte de sensor de lluvia")
    agregar("G-10-58-25", CLASE_58, "L2", "Al dar marcha atras con limpiaparabrisas delantero encendido, el barrido automatico del vidrio trasero no activa por motor trasero quemado sin consumo de amperios.", "TECNICO", "RETROCESO_BARRIDO_AUTO", "barrido_trasero_reversa_falla, motor_sin_consumo", "falla_cierre_maletero", "", "NO", "SI", CLASE_55, "L2 limpiador trasero reversa vs cierre maletero")

    # L3 (15 casos)
    agregar("G-10-58-26", CLASE_58, "L3", "Diagnostico de motor de limpiaparabrisas con pinza amperimetrica: en velocidad baja (Low) el consumo de corriente se dispara a 18.2 Amperios (especificacion nominal 2.5A a 4.0A con cristal humedo). Desmontaje confirma colector de delgas de inducido en cortocircuito franco con laminillas de cobre quemadas y barniz derretido.", "TECNICO", "PINZA_AMPERIMETRICA_CORRIENTE", "consumo_18_2a_sobrecorriente, delgas_inducido_en_corto, barniz_derretido", "falla_alternador", "", "NO", "SI", CLASE_47, "L3 corriente 18.2A por inducido en cortocircuito")
    agregar("G-10-58-27", CLASE_58, "L3", "Inspeccion de sistema de parada automatica (Park Switch): medicion de continuidad con multimetro en terminal de retorno a masa revela que las pistas circulares de cobre de la rueda dentada reductora presentan desgaste total con rotura de lengueta de contacto, provocando que el motor corte en cualquier punto aleatorio.", "TECNICO", "MULTIMETRO_PARK_SWITCH", "pistas_cobre_reductora_desgastadas, lengueta_rota, parada_aleatoria", "falla_rele_bcm", "", "NO", "NO", "", "L3 pistas de cobre y lengueta de park switch rotas")
